$_wpx_lang = defined('LANG') ? (int)LANG : (isset($LANG_ID) ? (int)$LANG_ID : 1);
$_wpx_nav = mysql_query("SELECT * FROM mod_menu WHERE parent = 0 AND lang_id = $_wpx_lang ORDER BY `order`");
if ($_wpx_nav) {
    while ($_wpx_m = mysql_fetch_array($_wpx_nav)) {
        $_wpx_show = true;
        if (isset($_wpx_m["show_m"]) && $_wpx_m["show_m"] !== "1" && $_wpx_m["show_m"] !== 1) { $_wpx_show = false; }
        if (!$_wpx_show) { continue; }
        $_wpx_link = (string) $_wpx_m["link"];
        if (function_exists('tenant_public_href')) { $_wpx_link = tenant_public_href($_wpx_link); }
        $_wpx_title = $_wpx_m["title"];
        $_wpx_id = (int)$_wpx_m["id"];
        $_wpx_sub = mysql_query("SELECT * FROM mod_menu WHERE parent = $_wpx_id AND lang_id = $_wpx_lang ORDER BY `order`");
        $_wpx_has_sub = false;
        $_wpx_sub_rows = [];
        if ($_wpx_sub) {
            while ($_wpx_s = mysql_fetch_array($_wpx_sub)) {
                $_wpx_slink = (string) ($_wpx_s['link'] ?? '');
                if (function_exists('tenant_public_href')) { $_wpx_slink = tenant_public_href($_wpx_slink); }
                if (isset($_wpx_s['show_m']) && $_wpx_s['show_m'] !== '1' && $_wpx_s['show_m'] !== 1) { continue; }
                if ($_wpx_slink === '' || $_wpx_slink === '#.' || preg_match('/\.html?$/i', $_wpx_slink)) { continue; }
                $_wpx_s['link'] = $_wpx_slink;
                $_wpx_sub_rows[] = $_wpx_s;
            }
            $_wpx_has_sub = count($_wpx_sub_rows) > 0;
        }
        if ($_wpx_has_sub) {
            echo "<li class=\"nav-item dropdown\">";
            echo "<a class=\"nav-link dropdown-toggle\" href=\"" . htmlspecialchars($_wpx_link, ENT_QUOTES) . "\" data-bs-toggle=\"dropdown\">" . htmlspecialchars($_wpx_title, ENT_QUOTES) . "</a>";
            echo "<ul class=\"dropdown-menu dropdown-menu-lg dropdown-menu-end\">";
            foreach ($_wpx_sub_rows as $_wpx_s) {
                echo "<li><a class=\"dropdown-item\" href=\"" . htmlspecialchars($_wpx_s["link"], ENT_QUOTES) . "\">" . htmlspecialchars($_wpx_s["title"], ENT_QUOTES) . "</a></li>";
            }
            echo "</ul></li>";
        } else {
            echo "<li class=\"nav-item\"><a class=\"nav-link\" href=\"" . htmlspecialchars($_wpx_link, ENT_QUOTES) . "\">" . htmlspecialchars($_wpx_title, ENT_QUOTES) . "</a></li>";
        }
    }
}
